package com.cpf.starter.soap;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.ws.client.core.WebServiceTemplate;import org.springframework.ws.client.support.interceptor.ClientInterceptor;@AutoConfiguration @EnableConfigurationProperties(CpfSoapProperties.class) @ConditionalOnProperty(prefix="cpf.integration.soap",name="enabled",havingValue="true") public class CpfSoapAutoConfiguration {@Bean @ConditionalOnMissingBean WebServiceTemplate cpfWebServiceTemplate(CpfSoapProperties p,org.springframework.beans.factory.ObjectProvider<ClientInterceptor[]> interceptors){p.validate();if(p.isWsSecurityRequired()&&interceptors.getIfAvailable()==null)throw new IllegalStateException("SOAP WS-Security requires a customer key/certificate interceptor");var t=new WebServiceTemplate();var i=interceptors.getIfAvailable();if(i!=null)t.setInterceptors(i);return t;}@Bean CpfSoapClient cpfSoapClient(WebServiceTemplate t,CpfSoapProperties p){return new CpfSoapClient(t,p);}}
